<?php
$edit=isset($_GET['edit'])?fetch_one('SELECT * FROM gallery_items WHERE id=?',[(int)$_GET['edit']]):null;
$rows=fetch_all('SELECT * FROM gallery_items ORDER BY sort_order,id DESC');
?>
<div class="split-layout">
<form method="post" enctype="multipart/form-data" class="panel form-panel live-form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="gallery_save"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><input type="hidden" name="old_image" value="<?= e($edit['image']??'') ?>"><div class="panel-head"><div><small>MEDYA KÜTÜPHANESİ</small><h2><?= $edit?'Görseli düzenle':'Galeri görseli ekle' ?></h2></div><?php if($edit):?><a href="?section=gallery">Yeni görsel +</a><?php endif; ?></div><div class="form-grid"><label>Başlık<input name="title" value="<?= e($edit['title']??'') ?>" data-live="gallery-title"></label><label>Kategori<input name="category" value="<?= e($edit['category']??'') ?>" data-live="gallery-category" placeholder="Maç, Antrenman, Tesis..."></label><label class="full">Açıklama<textarea name="caption" data-live="gallery-caption"><?= e($edit['caption']??'') ?></textarea></label><label>Görsel dosyası<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp,image/gif" data-image-preview="gallery-image"></label><label>Görsel URL<input name="image_url" data-url-preview="gallery-image" placeholder="https://..."></label><label>Sıralama<input type="number" name="sort_order" value="<?= e($edit['sort_order']??0) ?>"></label><label class="check"><input type="checkbox" name="active" <?= ($edit['active']??1)?'checked':'' ?>><span>Galeride göster</span></label></div><div class="upload-note"><b>Galeri görseli önerisi</b><span>JPG/WEBP, en az 1400 px genişlik. Yatay 1600×1000, dikey 1200×1600 veya kare 1200×1200 kullanılabilir.</span></div><button class="primary-button">Görseli Kaydet</button></form>
<aside class="preview-column sticky-preview"><div class="preview-label">CANLI GALERİ KARTI</div><figure class="gallery-admin-preview"><img id="gallery-image" src="<?= e(!empty($edit['image'])?media_url($edit['image']):placeholder_logo()) ?>" alt=""><figcaption><small data-preview="gallery-category"><?= e($edit['category']??'KATEGORİ') ?></small><h3 data-preview="gallery-title"><?= e($edit['title']??'Görsel başlığı') ?></h3><p data-preview="gallery-caption"><?= e($edit['caption']??'Görsel açıklaması') ?></p></figcaption></figure></aside></div>
<section class="panel"><div class="panel-head"><div><small>GALERİ AKIŞI</small><h2>Yüklenen görseller</h2></div><span><?= count($rows) ?> görsel</span></div><div class="gallery-admin-grid"><?php foreach($rows as $row):?><article><img src="<?= e(media_url($row['image'])) ?>" alt=""><div><small><?= e($row['category']) ?></small><h3><?= e($row['title']) ?></h3><p><?= e($row['caption']) ?></p></div><span class="badge <?= $row['active']?'green':'gray' ?>"><?= $row['active']?'Yayında':'Gizli' ?></span><div class="row-actions"><a href="?section=gallery&edit=<?= $row['id'] ?>">Düzenle</a><form method="post" onsubmit="return confirm('Görsel silinsin mi?')"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="delete_generic"><input type="hidden" name="table" value="gallery_items"><input type="hidden" name="id" value="<?= $row['id'] ?>"><button class="danger-link">Sil</button></form></div></article><?php endforeach; ?><?php if(!$rows):?><div class="empty-admin">Henüz galeri görseli yok.</div><?php endif; ?></div></section>
